INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c10b-7e4a-a312-9bdad7d859f3'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A shop sells watches at $210 each. Jimmy buys them at a 20% discount and then sells them at a 20% profit with a 10% discount on the marked price. Find the marked price.', '$224', 'Jimmy''s cost price is 80% of 210, so it is 168. To make a 20% profit, he needs to sell at 201.60. If this is after a 10% discount, then the marked price is 201.60 ÷ 0.9 = 224.', 'Medium', '{"tags":"percentages,profit-and-loss,discount","subtopic":"profit and discount","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.763Z'::timestamptz, '2026-07-26T14:06:34.763Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c10f-7fcc-8d04-77445751fea6'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A student walks 1000 metres at 4 km/h, takes a 5 minute break, then runs 1.3 km in 5 minutes. Will the whole exercise be completed by 09:30 if the student starts at 08:50?', 'Yes', 'Walking 1000 m at 4 km/h takes 15 minutes. Add the 5 minute break and 5 minutes running for a total of 25 minutes. Starting at 08:50 means the student finishes at 09:15, which is before 09:30.', 'Easy', '{"tags":"numbers,time,speed","subtopic":"time and speed","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.767Z'::timestamptz, '2026-07-26T14:06:34.767Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6c8-7467-94c3-4dc43c0fbd39'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Find the first negative term of the sequence whose nth term is 87 - 9n.', 'The 10th term (-3)', 'Solve 87 - 9n < 0. Then 9n > 87, so n > 9.666... The smallest integer n is 10. The 10th term is 87 - 90 = -3.', 'Medium', '{"tags":"algebra,sequences,inequalities","subtopic":"sequence inequalities","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.864Z'::timestamptz, '2026-07-26T12:42:25.864Z'::timestamptz) ON CONFLICT (id) DO NOTHING;